// Helper to create an instance or clone
async function createInstance(nodeId) {
    const node = figma.getNodeById(nodeId);
    if (!node) return null;
    if (node.type === 'COMPONENT') {
        return node.createInstance();
    } else {
        return node.clone();
    }
}

